/* Layout shared by the TISP AE code and sensor bridge.  Keep the backing
 * object byte-addressable for the rest of the recovered code, but name the
 * fields used on the live initialization path so a byte index cannot silently
 * turn into a function pointer again. */
struct t21_sensor_ctrl_view {
	u8 reserved_00[0x18];
	u32 exp2_input_a;
	u32 exp2_input_b;
	u32 min_integration_time;
	u32 max_integration_time;
	u8 reserved_28[0x0a];
	u8 timing_32;
	u8 timing_33;
	u8 timing_34;
	u8 reserved_35[0x13];
	int32_t (*hw_reset_disable)(void);
	void (*hw_reset_enable)(void);
	int32_t (*alloc_analog_gain)(int32_t, int16_t *);
	int32_t (*alloc_digital_gain)(int32_t, void *);
	int32_t (*alloc_integration_time)(int16_t *);
	uint32_t (*set_integration_time)(uint32_t);
	int32_t (*start_changes)(void);
	int32_t (*end_changes)(void);
	uint32_t (*set_analog_gain)(uint32_t);
	uint32_t (*set_digital_gain)(uint32_t);
	uint32_t (*get_normal_fps)(void);
	int32_t (*read_black_pedestal)(void);
	uint32_t (*set_mode)(uint32_t, uintptr_t);
	int32_t (*set_wdr_mode)(void);
	int64_t (*fps_control)(uint32_t, uintptr_t);
	uint32_t (*get_id)(void);
	int32_t (*disable_isp)(void);
	int32_t (*get_lines_per_second)(void);
};

/* tisp_ae_ctrls, the 64-byte live AE record.  Gains are linear Q10
 * (1024 = 1x).  Offsets 0x24..0x2c follow the stock tisp_ae_process_impl
 * and tisp_g_ev_attr (libt21-firmware 1.0.33): 0x24 is the exposure value
 * that event 6 carries (integration lines x total gain, Q10), 0x28 the
 * log2 of the total gain and 0x2c the log2 of the analogue gain, both Q16. */
struct t21_ae_ctrls_view {
	u32 manual_mode;
	u32 sensor_again;
	u32 sensor_dgain;
	u32 integration_time;
	u32 isp_dgain;
	u32 max_sensor_again;
	u32 max_sensor_dgain;
	u32 max_integration_time;
	u32 max_isp_dgain;
	u32 ev_q10;
	u32 total_gain_log2;
	u32 again_log2;
	u32 reserved_30;
	/* 0x34: integration time fixed (stock tisp_ae_manual_set, SetExpr
	 * MANUAL): tisp_set_sensor_integration_time then writes the lines at
	 * 0x0c instead of the AE's value, and ae_tune2 moves only the gain. */
	u32 it_manual;
	u8 reserved[0x40 - 0x38];
};

struct t21_ev_sensor_info_view {
	u8 reserved_00[0x2c];
	u32 fps;			/* numerator << 16 | denominator */
	u8 reserved_30[0x0e];
	u16 total_lines;		/* frame length (VTS) in lines */
};

/* The twelve-word record tisp_g_ev_attr fills.  Field order and sources are
 * those of the stock body; the stock isp_info_show prints them as
 * "SENSOR Integration Time" (0x00), "ISP EV value" (0x04), "ISP EV value us"
 * (0x08), "ISP EV value log2" (0x0c), "SENSOR analog gain" (0x10),
 * "ISP digital gain" (0x14), "ISP Tgain DB" (0x18), "MAX SENSOR analog gain"
 * (0x20), "MAX ISP digital gain" (0x24), "SENSOR digital gain" (0x28) and
 * "MAX SENSOR digital gain" (0x2c).  Gains are IMP log2 units (Q5, 32 per
 * doubling); 0x1c is the linear total gain in [24.8] (256 = 1x) that
 * TOTAL_GAIN (0x8000027) returns. */
struct t21_ev_attr_view {
	u32 integration_time;
	u32 ev;
	u32 expr_us;
	u32 ev_log2;
	u32 sensor_again_log2;
	u32 isp_dgain_log2;
	u32 total_gain_db;
	u32 total_gain_q8;
	u32 max_sensor_again_log2;
	u32 max_isp_dgain_log2;
	u32 sensor_dgain_log2;
	u32 max_sensor_dgain_log2;
};

/* IMPISPEVAttr of the T21 SDK: words 1..6 of the record above. */
struct t21_ev_user_view {
	u32 ev;
	u32 expr_us;
	u32 ev_log2;
	u32 again;
	u32 dgain;
	u32 gain_log2;
};

/* The tuning core keeps white balance as seven 32-bit words, while the
 * userspace control ABI exposes only mode plus two 16-bit gains.  The last
 * four words are scalar control results: WB_STATS returns statis_rg/bg and
 * WB_GOL_STATS returns global_rg/bg, packed as two 16-bit values.  Keep the
 * internal and userspace records separate so no caller can accidentally
 * treat the eight-byte ABI object as the complete controller state. */
struct t21_wb_internal_view {
	u32 mode;
	u32 manual_rgain;
	u32 manual_bgain;
	u32 statis_rgain;
	u32 statis_bgain;
	u32 global_rgain;
	u32 global_bgain;
};

struct t21_wb_user_view {
	u32 mode;
	u16 rgain;
	u16 bgain;
};

struct t21_sensor_bridge_state {
	u8 reserved_000[0x60];
	u32 analog_gain;
	u8 reserved_064[0x0c];
	u32 integration_time;
	u8 reserved_074[0x18];
	u32 combined_exposure;
};

struct t21_sensor_bridge_runtime {
	u8 reserved_000[0x120];
	struct t21_sensor_bridge_state *sensor;
	u8 reserved_124[0x54];
	u32 analog_gain_pending;
	u32 analog_gain;
	u32 digital_gain_pending;
	u32 digital_gain;
	u32 integration_time_pending;
	u32 integration_time;
	u32 combined_exposure_pending;
	u32 combined_exposure;
};

struct t21_sensor_update {
	u32 pending;
	u32 value;
};

/*
 * Sensor exposure write cache.  Stock sensor_set_integration_time /
 * sensor_set_analog_gain (vendor 0x8f40 / 0x8f90) return without queueing an
 * update when the AE value equals the one the sensor already has, so a
 * converged AE writes nothing.  The recovery queued every frame (2-3 i2c
 * transfers per frame, ~51 i2c IRQs/s against 0.1/s on the vendor stack).
 * As on T20, the cache is only valid while the sensor keeps its registers:
 * set_input (IMP_ISP_EnableSensor) reloads the sensor's init table, so the
 * next AE value is written once even if it equals the cached one.
 * t21_sensor_write_always=1 restores the per-frame writes.
 */
#define T21_SENSOR_STALE_IT	0
#define T21_SENSOR_STALE_AGAIN	1
static unsigned long t21_sensor_regs_stale = ~0UL;
static int t21_sensor_write_always;
module_param(t21_sensor_write_always, int, 0644);
MODULE_PARM_DESC(t21_sensor_write_always, "1 queues the sensor exposure/gain every frame even when unchanged (default 0: only on change, as stock)");
static unsigned int t21_sensor_writes_skipped;
module_param(t21_sensor_writes_skipped, uint, 0444);
static unsigned int t21_sensor_rearm_count;
module_param(t21_sensor_rearm_count, uint, 0444);
static unsigned int t21_sensor_rearm_writes;
module_param(t21_sensor_rearm_writes, uint, 0444);

/* true when the value has to be queued for the sensor */
static bool t21_sensor_reg_changed(int slot, u32 cached, u32 value)
{
	bool stale = test_and_clear_bit(slot, &t21_sensor_regs_stale);

	if (cached != value || t21_sensor_write_always)
		return true;
	if (stale) {
		t21_sensor_rearm_writes++;
		return true;
	}
	t21_sensor_writes_skipped++;
	return false;
}

static void t21_sensor_exposure_invalidate(void)
{
	set_bit(T21_SENSOR_STALE_IT, &t21_sensor_regs_stale);
	set_bit(T21_SENSOR_STALE_AGAIN, &t21_sensor_regs_stale);
	t21_sensor_rearm_count++;
}

