static u32 t21_ae_target_for_exposure(u32 exposure)
{
	const u32 *ev = (const u32 *)_ev_list;
	const u32 *at = (const u32 *)_at_list;
	u32 i;

	if (exposure <= ev[0])
		return at[0];
	if (exposure >= ev[9])
		return at[9];

	for (i = 0; i < 9; i++) {
		u32 span;
		u32 pos;

		if (exposure > ev[i + 1])
			continue;
		span = ev[i + 1] - ev[i];
		if (!span)
			return at[i];
		pos = exposure - ev[i];
		if (at[i + 1] >= at[i])
			return at[i] + (at[i + 1] - at[i]) * pos / span;
		return at[i] - (at[i] - at[i + 1]) * pos / span;
	}

	return at[9];
}

