		memcpy(p, (const void *)(uintptr_t)(data), 0x50);
		expected_size = 0x50;
		break;
	case 0x10:
		p = (int32_t *)_ae_zone_weight;
		memcpy(p, (const void *)(uintptr_t)(data), 0x384);
		expected_size = 0x384;
		break;
