static bool t21_isp_valid_ptr(const void *ptr)
{
	return ptr && (uintptr_t)ptr < (uintptr_t)-4095;
}

static int t21_isp_mbus_code_to_bayer(u32 code)
{
	switch (code) {
	case 0x300d:
	case 0x300f:
	case 0x3012:
	case 0x3014:
		return 0;
	case 0x3002:
	case 0x3009:
	case 0x300a:
	case 0x3011:
		return 1;
	case 0x3001:
	case 0x3003:
	case 0x3004:
	case 0x3005:
	case 0x3006:
	case 0x3007:
	case 0x3008:
	case 0x300b:
		return 2;
	case 0x300c:
	case 0x300e:
	case 0x3010:
	case 0x3013:
		return 3;
	default:
		break;
	}

	if ((code >= 0x3100 && code <= 0x310f) ||
	    (code >= 0x3200 && code <= 0x320f) ||
	    (code >= 0x3300 && code <= 0x330f))
		return 4 + (code & 0xf);

	return -EINVAL;
}

